--changeset zofolio:seed-en-projects (copy-en-v1-v2.md, validé par Enzo 2026-10-16)
UPDATE project SET title = title || '{"en": "Oltre"}'::jsonb, pitch = pitch || '{"en": "A personal app to organize work and personal life in one full calendar: sport, expenses, tasks, appointments."}'::jsonb, duration = duration || '{"en": "Ongoing"}'::jsonb, note = note || '{"en": "Project started in June 2026. Commits: back end and front end."}'::jsonb, role = role || '{"en": "Design and development, alone and from scratch: back end, front end, and setting up Spring Boot and Angular"}'::jsonb, problem = problem || '{"en": "My daily life was scattered: runs in Garmin, expenses in one place, tasks and appointments in another. I wanted to see everything in one place, with my sports activities in it."}'::jsonb, wall = wall || '{"en": "The hardest part wasn''t the code: it was pinning down my idea and giving it shape. Going from a fuzzy need, organizing my work and personal life, to a concrete product."}'::jsonb, takeaway = takeaway || '{"en": "Depending on an unofficial API means planning from day one where it will break, and telling the user plainly."}'::jsonb, ai_note = ai_note || '{"en": "Started by hand, then continued with AI help."}'::jsonb, video = jsonb_set(video, '{caption,en}', to_jsonb('A walk through Oltre: expenses, tasks, meals. Dummy data.'::text))
WHERE slug = 'oltre';
UPDATE project SET title = title || '{"en": "Zotracker"}'::jsonb, pitch = pitch || '{"en": "Live GPS tracking of a foot race: my loved ones follow me on a map, with nothing to install."}'::jsonb, duration = duration || '{"en": "Since October 2026"}'::jsonb, note = note || '{"en": "Private alerts (SOS, stationary, off route) notify loved ones, and the start area is hidden on the public trace. A simulation mode lets me test everything without running."}'::jsonb, role = role || '{"en": "Design and development"}'::jsonb, problem = problem || '{"en": "Zotracker was born for the Lille marathon: my parents, family and friends wanted to follow me live. It runs in the browser, with no app to install, and I plan to reuse it on other races."}'::jsonb, wall = wall || '{"en": "On race day, anything can give out: the network drops, the browser GPS shuts off when the screen locks (on iPhone), and safety alerts must still go out. Points are queued when the network drops; the rest of that reliability is still to be built."}'::jsonb, takeaway = takeaway || '{"en": "An app used on race day isn''t judged by its demo: it''s judged at the worst moment of the race. Hence the simulation mode, to test without running."}'::jsonb, ai_note = ai_note || '{"en": "Designed with AI."}'::jsonb, video = jsonb_set(video, '{caption,en}', to_jsonb('A simulated race on the official Grand Trail d''Auvergne route.'::text))
WHERE slug = 'zotracker';
UPDATE project SET title = title || '{"en": "GFaim"}'::jsonb, pitch = pitch || '{"en": "A meal planner for a family, my final-year project."}'::jsonb, duration = duration || '{"en": "January to March 2025"}'::jsonb, role = role || '{"en": "Team of four. I handled both front end and back end."}'::jsonb, problem = problem || '{"en": "A professor wanted a meal planner for his family. The starting specification was fixed: we had to follow it. After that, the freedom to innovate beyond it."}'::jsonb, wall = wall || '{"en": "Getting four people''s ideas to converge, and meeting the delivery deadlines."}'::jsonb, takeaway = takeaway || '{"en": "A good result, and a good team experience."}'::jsonb
WHERE slug = 'gfaim';
UPDATE project SET title = title || '{"en": "Trading application at Worldline"}'::jsonb, pitch = pitch || '{"en": "For 2.5 years, I worked on an application that lets finance professionals buy and sell securities on the stock market."}'::jsonb, duration = duration || '{"en": "2.5 years of professional experience (March 2023 to September 2025)"}'::jsonb, role = role || '{"en": "Back-end developer, then full-stack"}'::jsonb, problem = problem || '{"en": "A trading application can''t afford approximation. When you buy or sell securities, a mistake doesn''t stay in a log file: it shows up in an order. My job: deliver complete changes, from analysing the need to production, in a Scrum team."}'::jsonb, wall = wall || '{"en": "The complexity of the solution, and meeting the Definition of Done: a change is only finished once everything is verified, tested and reviewed."}'::jsonb, takeaway = takeaway || '{"en": "Working on a critical system taught me rigour: analyse before coding, test before shipping, and keep a cool head when everything moves fast."}'::jsonb
WHERE slug = 'trading-app';
UPDATE project SET decisions = decisions || '{"en": [{"title": "Garmin in a separate service", "tradeoff": "Garmin offers no official access: I use an unofficial library, which I isolated from the back end. One more service to run and protect, but a fragile dependency that doesn''t contaminate the rest. And when Garmin refuses the connection, the real error reaches the screen instead of a vague message."}, {"title": "Gemini rather than Anthropic for the AI coach", "tradeoff": "Gemini has a free tier, the Anthropic API doesn''t: for a personal project, the choice was quick. Downside: the coach stays silent without a key, and the model name has already needed a fix."}, {"title": "Login lockout by email and by IP", "tradeoff": "A stranger can''t lock my account from their own machine. Downside: the counter lives in memory, resets to zero on restart and isn''t shared across instances."}]}'::jsonb
WHERE slug = 'oltre';
UPDATE project SET decisions = decisions || '{"en": [{"title": "JSON files rather than a database", "tradeoff": "No service to run or back up. Downside: disk writes are on me. I''ve already added a retry on failure and a refusal to start if the file is corrupted."}, {"title": "A vanilla JavaScript front end, no bundler", "tradeoff": "No build step. Downside: duplicated code between server and browser. Statistics are computed twice, and the two results already diverge on the estimated finish time before the start."}, {"title": "Distance computed on the GPX route", "tradeoff": "Distance follows the official course, without the GPS zigzag. Points more than 100 m away are ignored, and a gap above 150 m shows \"off route\". Without a GPX file, the server falls back to raw points, which are less accurate."}]}'::jsonb
WHERE slug = 'zotracker';
UPDATE project SET decisions = decisions || '{"en": [{"title": "Tokens signed with RSA", "tradeoff": "The signature is checked with a public key, and the private key stays safe. Downside: generating and distributing keys is done by hand."}, {"title": "A dedicated certificate for the Spoonacular API", "tradeoff": "The HTTPS connection goes through a certificate imported by hand. Downside: a manual step to repeat on every machine."}]}'::jsonb
WHERE slug = 'gfaim';
UPDATE project SET decisions = decisions || '{"en": [{"title": "Testing in real conditions", "tradeoff": "A hard-coded date hid a bug until production. Since then, I test under conditions close to the real thing, which takes more preparation time before delivery."}, {"title": "Validating the mock-up before coding", "tradeoff": "On a feature I carried alone in my final year, I had the Product Owner validate the mock-up before development. One more exchange up front, but fewer rework loops along the way."}]}'::jsonb
WHERE slug = 'trading-app';
